const buffer = msg.payload;
const topic = msg.topic;

if (!buffer) {
    msg.payload = { error: 'Invalid parameters' };
    msg.topic = 'lora/out/error';
    return msg;
}

const messageType = buffer.readUInt8(0);
let packet = {};

try {
    if (messageType === 0x01 && buffer.length === 27) {
        const nodeId = buffer.readUInt32LE(1);
        if (nodeId === 0) {
            msg.payload = { error: 'Invalid packet data - nodeId is 0' };
            msg.topic = 'lora/out/error';
            return msg;
        }
        packet = {
            type: 'sensor',
            nodeId: nodeId,
            counter: buffer.readUInt32LE(5),
            uptime: buffer.readUInt32LE(9),
            battery: buffer.readUInt8(13),
            voltage: buffer.readUInt16LE(14),
            analog: [
                buffer.readUInt16LE(16),
                buffer.readUInt16LE(18),
                buffer.readUInt16LE(20),
                buffer.readUInt16LE(22)
            ],
            digital: buffer.readUInt8(24)
        };
        msg.topic = 'lora/out/sensor';
    } else if (messageType === 0x02 && buffer.length === 35) {
        const nodeId = buffer.readUInt32LE(1);
        const latitude = buffer.readFloatLE(16);
        const longitude = buffer.readFloatLE(20);
        if (nodeId === 0 || latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
            msg.payload = { error: 'Invalid packet data' };
            msg.topic = 'lora/out/error';
            return msg;
        }
        packet = {
            type: 'gnss',
            nodeId: nodeId,
            counter: buffer.readUInt32LE(5),
            uptime: buffer.readUInt32LE(9),
            battery: buffer.readUInt8(13),
            voltage: buffer.readUInt16LE(14),
            latitude: latitude,
            longitude: longitude,
            speed: buffer.readFloatLE(24),
            hdop: buffer.readUInt8(28) / 10.0,
            course: buffer.readFloatLE(29)
        };
        msg.topic = 'lora/out/gnss';
    } else {
        msg.payload = { error: `Unknown packet: type=0x${messageType.toString(16).padStart(2, '0').toUpperCase()}, length=${buffer.length}` };
        msg.topic = 'lora/out/error';
        return msg;
    }
} catch (e) {
    msg.payload = { error: `Parsing error: ${e.message}` };
    msg.topic = 'lora/out/error';
    return msg;
}

msg.payload = packet;
return msg;

const rows = msg.payload;
const sensorData = msg.sensorData;

if (!rows || rows.length === 0) {
    node.warn('Unknown device for nodeId: ' + msg.nodeId);
    node.send([null, null, {nodeId: msg.nodeId, sensorData: sensorData}]);
    return null;
}

const device = rows[0];
const alerts = [];

if (device.digital_pins && sensorData.digital !== undefined) {
    device.digital_pins.forEach(pin => {
        const pinState = (sensorData.digital >> pin.pin_index) & 1;
        if (pin.trigger === 'High' && pinState === 1) {
            alerts.push({deviceId: device.device_id, ownerName: device.owner_name, ownerEmail: device.owner_email, notifyVia: device.notify_via, deviceName: device.display_name, nodeId: msg.nodeId, pinLabel: pin.label, alertMessage: 'Triggered HIGH', alertLevel: pin.alert_level});
        } else if (pin.trigger === 'Low' && pinState === 0) {
            alerts.push({deviceId: device.device_id, ownerName: device.owner_name, ownerEmail: device.owner_email, notifyVia: device.notify_via, deviceName: device.display_name, nodeId: msg.nodeId, pinLabel: pin.label, alertMessage: 'Triggered LOW', alertLevel: pin.alert_level});
        }
    });
}

if (device.analog_pins && sensorData.analog) {
    device.analog_pins.forEach(pin => {
        const value = sensorData.analog[pin.pin_index];
        if (value === undefined) return;
        if (pin.low_threshold !== null && value < pin.low_threshold) {
            alerts.push({deviceId: device.device_id, ownerName: device.owner_name, ownerEmail: device.owner_email, notifyVia: device.notify_via, deviceName: device.display_name, nodeId: msg.nodeId, pinLabel: pin.label, alertMessage: `Analog value LOW: ${value}`, alertLevel: pin.alert_level});
        } else if (pin.high_threshold !== null && value > pin.high_threshold) {
            alerts.push({deviceId: device.device_id, ownerName: device.owner_name, ownerEmail: device.owner_email, notifyVia: device.notify_via, deviceName: device.display_name, nodeId: msg.nodeId, pinLabel: pin.label, alertMessage: `Analog value HIGH: ${value}`, alertLevel: pin.alert_level});
        }
    });
}

const logMsg = {
    query: 'INSERT INTO events (device_id, node_id, message_type, payload) VALUES ($1, $2, $3, $4::jsonb)',
    params: [device.device_id, msg.nodeId, sensorData.type, JSON.stringify(sensorData)],
    payload: ''
};
node.send([null, logMsg, null]);

if (alerts.length > 0) {
    alerts.forEach(alert => {
        const alertMsg = {
            query: 'INSERT INTO alerts (device_id, pin_label, alert_message, alert_level) VALUES ($1, $2, $3, $4) ON CONFLICT (device_id, pin_label) DO UPDATE SET alert_message = EXCLUDED.alert_message, count = alerts.count + 1, updated_at = NOW()',
            params: [alert.deviceId, alert.pinLabel, alert.alertMessage, alert.alertLevel],
            payload: '',
            alert: alert
        };
        node.send([alertMsg, null, null]);
    });
} else {
    node.log('No alerts for nodeId: ' + msg.nodeId);
}

return null;

const alert = msg.alert;
if (!alert) return null;

const key = `notified_${alert.deviceId}_${alert.pinLabel.replace(/\s+/g, '_')}`;
const lastNotified = flow.get(key) || 0;
const now = Date.now();
const cooldownMs = 5 * 60 * 1000;

if (now - lastNotified < cooldownMs) {
    node.log(`Notification suppressed (cooldown): ${alert.pinLabel}`);
    return null;
}
flow.set(key, now);

const transporter = nodemailer.createTransport({
    host: 'smtp.gmail.com',
    port: 465,
    secure: true,
    auth: {
        user: env.get('NOTIFY_EMAIL_USER'),
        pass: env.get('NOTIFY_EMAIL_PASS')
    }
});

const recipient = alert.ownerEmail;
if (!recipient) {
    node.warn('No email for owner: ' + alert.ownerName);
    return null;
}

const subject = `SensorSentinel Alert: ${alert.pinLabel} on ${alert.deviceName}`;
const body = `Alert for ${alert.ownerName}\n\nDevice: ${alert.deviceName}\nSensor: ${alert.pinLabel}\nMessage: ${alert.alertMessage}\nLevel: ${alert.alertLevel}\nTime: ${new Date().toISOString()}`;

transporter.sendMail({
    from: '"SensorSentinel" <' + env.get('NOTIFY_EMAIL_USER') + '>',
    to: recipient,
    subject: subject,
    text: body
}).then(() => {
    node.log('Notification sent to ' + recipient);
}).catch(err => {
    node.error('Notification failed: ' + err.message);
});

return msg;

const nodeId = msg.nodeId;
const displayName = 'Node-' + nodeId.toString(16).padStart(8, '0').toUpperCase();
msg.query = 'INSERT INTO devices (node_id, display_name) VALUES ($1, $2) ON CONFLICT (node_id) DO NOTHING';
msg.params = [nodeId, displayName];
msg.newDeviceName = displayName;
return msg;

msg.topic = 'sentinel/new_device';
msg.payload = JSON.stringify({
    nodeId: msg.nodeId,
    displayName: msg.newDeviceName,
    firstSeen: new Date().toISOString()
});
return msg;

// Unwrap the HT-M7603 gateway envelope into the raw LoRa payload.
// Gateway publishes JSON to GWID/<eui>/UP with the payload base64-encoded.
// Downstream flows expect a bare Buffer on lora/in/#, so translate and
// republish, preserving radio metadata on msg.gateway.

let env = msg.payload;

// payload may arrive as Buffer/string depending on the mqtt node's output mode
if (Buffer.isBuffer(env)) env = env.toString('utf8');
if (typeof env === 'string') {
    try { env = JSON.parse(env); }
    catch (e) {
        node.warn('gateway: payload is not JSON: ' + String(env).slice(0, 80));
        return null;
    }
}
if (!env || typeof env !== 'object' || !env.data) {
    node.warn('gateway: no data field in envelope');
    return null;
}

let buf;
try { buf = Buffer.from(env.data, 'base64'); }
catch (e) { node.warn('gateway: base64 decode failed'); return null; }

if (!buf.length) { node.warn('gateway: empty payload'); return null; }

// sanity-check against the two known packet shapes before passing it on
const t = buf.readUInt8(0);
if (!((t === 0x01 && buf.length === 27) || (t === 0x02 && buf.length === 35))) {
    node.warn('gateway: unrecognised packet type=0x' + t.toString(16) +
              ' len=' + buf.length + ' (expected 0x01/27 or 0x02/35)');
    // still forward it - the parser reports its own error, and seeing the
    // rejection downstream is more useful than dropping it silently here
}

msg.gateway = {
    eui:  (msg.topic || '').split('/')[1] || null,
    freq: env.freq  !== undefined ? env.freq  : null,
    datr: env.datr  !== undefined ? env.datr  : null,
    rssi: env.rssi  !== undefined ? env.rssi  : null,
    snr:  env.lsnr  !== undefined ? env.lsnr  : null,
    size: env.size  !== undefined ? env.size  : buf.length
};

node.status({ fill: 'green', shape: 'dot',
              text: 'rx ' + buf.length + 'B rssi ' + msg.gateway.rssi });

msg.payload = buf;
msg.topic = 'lora/in/gw';
return msg;

// Semtech UDP packet forwarder -> the same MQTT envelope the HT-M7603 emits,
// so a Dragino/RAK/sx1302_hal gateway feeds the Gateway Adapter below without a
// second translation path, and no vendor's proprietary MQTT mode can trap us.
//
//   byte  0     protocol version (0x02)
//   bytes 1-2   token, echoed in the ACK
//   byte  3     packet type
//   bytes 4-11  gateway EUI (PUSH_DATA / PULL_DATA)
//   bytes 12+   JSON payload (PUSH_DATA only)

const PUSH_DATA = 0x00, PUSH_ACK = 0x01;
const PULL_DATA = 0x02, PULL_ACK = 0x04;

const buf = msg.payload;
if (!Buffer.isBuffer(buf) || buf.length < 4) { return null; }

const token = buf.slice(1, 3);
const kind = buf[3];

// A forwarder that gets no ACK decides the server is down and starts buffering,
// so acknowledge before anything that might fail.
if (kind === PULL_DATA) {
    // Downlink keepalive. We never transmit, but without the ACK the gateway
    // logs the server as unreachable.
    const pull = Buffer.concat([Buffer.from([0x02]), token, Buffer.from([PULL_ACK])]);
    return [{ payload: pull, ip: msg.ip, port: msg.port }, null];
}
if (kind !== PUSH_DATA) { return null; }

const ack = Buffer.concat([Buffer.from([0x02]), token, Buffer.from([PUSH_ACK])]);
const ackMsg = { payload: ack, ip: msg.ip, port: msg.port };

if (buf.length < 12) { return [ackMsg, null]; }
const eui = buf.slice(4, 12).toString('hex').toUpperCase();

const body = buf.slice(12);
if (body.length === 0) { return [ackMsg, null]; }   // keepalive with no payload

let parsed;
try {
    parsed = JSON.parse(body.toString('utf8'));
} catch (e) {
    node.warn('udp: undecodable JSON from ' + msg.ip + ' (' + body.length + ' bytes)');
    return [ackMsg, null];
}

// freq/datr/rssi/lsnr/size/data already match the Heltec envelope; the extra
// Semtech fields (tmst, chan, codr) are ignored downstream.
const out = [];
for (const rxpk of (parsed.rxpk || [])) {
    out.push({ topic: 'GWID/' + eui + '/UP', payload: rxpk });
}

if (out.length > 0) {
    node.status({ fill: 'green', shape: 'dot', text: eui + ' ' + out.length + ' pkt' });
}
return [ackMsg, out];

// One physical transmission can reach us by several independent paths: the
// HT-M7603 via GWID/<eui>/UP, a Heltec receiver via lora/in, and any second
// gateway added later. Each forwards without knowing the others exist, so the
// on-device caches (_seenPackets in the repeater, receivedCache in the
// receiver) cannot catch it - they only ever see their own copy.
//
// Time-windowed rather than a UNIQUE index on (node_id, counter):
// sensorPacketCounter is RTC_DATA_ATTR, so it survives deep sleep but RESETS
// TO 0 on power loss. A permanent constraint would silently reject valid
// packets from any node that had been power-cycled.

const WINDOW_MS = 120000;   // ~2 min: far longer than any path's delivery skew

const p = msg.payload || {};
const nodeId = p.nodeId;
const counter = p.counter;

// Anything we cannot key on is passed through rather than dropped: losing real
// data would be worse than storing an occasional duplicate.
if (nodeId === undefined || counter === undefined) {
    node.warn('dedupe: payload missing nodeId/counter, passing through');
    return [msg, null];
}

const key = nodeId + ':' + (p.type || 'sensor') + ':' + counter;
const now = Date.now();
const seen = context.get('seen') || {};

// Prune before the lookup so the object cannot grow without bound.
for (const k in seen) {
    if (now - seen[k] > WINDOW_MS) { delete seen[k]; }
}

if (seen[key] !== undefined) {
    const age = now - seen[key];
    const dropped = (context.get('dropped') || 0) + 1;
    context.set('dropped', dropped);
    context.set('seen', seen);
    node.status({ fill: 'yellow', shape: 'ring', text: 'dropped ' + dropped + ' dup' });
    msg.dedupe = { key: key, ageMs: age, dropped: dropped };
    return [null, msg];
}

seen[key] = now;
context.set('seen', seen);
node.status({ fill: 'green', shape: 'dot', text: 'pass ' + key });
return [msg, null];
